// === IDM 参数 ===
const double IDM_V0 = 30.0;       // 期望速度 m/s
const double IDM_T = 1.5;         // 安全时距 s
const double IDM_S0 = 2.0;        // 最小间距 m
const double IDM_A_MAX = 2.0;     // 最大加速度 m/s²
const double IDM_B_COMF = 1.5;    // 舒适减速度 m/s²
const double IDM_DELTA = 4.0;     // 加速度指数

void findVehicleAhead(double &gap, double &vLead) {
    int i = 0;
    double minDist = 1000000.0;
    double egoX = 0.0, egoY = 0.0, obsX = 0.0, obsY = 0.0;
    double egoDirX = 0.0, egoDirY = 0.0;
    double projDist = 0.0, absDist = 0.0;

    gap = 1000000.0;
    vLead = 0.0;

    egoX = i2d(cps_i_state.position.x);
    egoY = i2d(cps_i_state.position.y);
    egoDirX = cos(i2d(cps_i_state.orientation));
    egoDirY = sin(i2d(cps_i_state.orientation));

    for (i = 0; i < MAXOBS; i++) {
        obsX = i2d(obs_i_state[i].position.x);
        obsY = i2d(obs_i_state[i].position.y);

        projDist = (obsX - egoX) * egoDirX + (obsY - egoY) * egoDirY;

        if (projDist > 0 && projDist < minDist) {
            minDist = projDist;
            absDist = sqrt(pow(obsX - egoX, 2.0) + pow(obsY - egoY, 2.0));
            gap = absDist;
            vLead = i2d(obs_i_state[i].velocity);
        }
    }
}

double computeIDM(double v, double vLead, double gap) {
    double s_star = 0.0;
    double acc = 0.0;
    double vRatio = 0.0;
    double gapRatio = 0.0;

    vRatio = v / IDM_V0;
    s_star = IDM_S0 + v * IDM_T +
             v * (v - vLead) / (2.0 * sqrt(IDM_A_MAX * IDM_B_COMF));

    if (gap < 0.001) {
        gap = 0.001;
    }
    gapRatio = s_star / gap;

    acc = IDM_A_MAX * (1.0 - pow(vRatio, IDM_DELTA) - pow(gapRatio, 2.0));

    return acc;
}

// === 法规驾驶员模型参数 ===
const double REACTION_TIME = 1.5;    // 反应时间 1.5 秒
const double BRAKE_RATE = 3.0;       // 刹车建立速率 m/s² 每秒
const double MAX_BRAKE = -8.0;       // 最大制动减速度
const double COMFORT_BRAKE = -4.0;   // 舒适制动减速度
const double TTC_EMERGENCY = 1.5;    // TTC 紧急制动阈值（秒）
const double TTC_WARNING = 3.0;      // TTC 预警制动阈值（秒）

int32_t reactionCount = 0;           // 反应计数器
bool dangerDetected = false;         // 危险标志

void makeDecision(){
    double gap = 1000000.0;
    double vLead = 0.0;
    double vEgo = 0.0;
    double ttc = 999.0;
    double targetAcc = 0.0;
    double currentAcc = 0.0;
    double accStep = 0.0;

    vEgo = i2d(cps_i_state.velocity);
    findVehicleAhead(gap, vLead);
    currentAcc = i2d(cps_i_state.acceleration);

    // 计算 TTC（碰撞时间）
    if (vEgo > vLead + 0.1) {
        ttc = gap / (vEgo - vLead);
    } else {
        ttc = 999.0;  // 不会碰撞
    }

    // === 法规模型决策逻辑 ===
    // 第一层：反应延迟（检测到危险后，需要 REACTION_TIME 才开始刹车）
    if (ttc < TTC_WARNING) {
        if (!dangerDetected) {
            dangerDetected = true;
            reactionCount = 0;
        }
        reactionCount++;
    } else {
        dangerDetected = false;
        reactionCount = 0;
    }

    // 第二层：根据 TTC 和反应状态决定目标加速度
    if (!dangerDetected) {
        // 安全区域：保持当前速度或轻微加速
        targetAcc = 0.5;
    } else if (reactionCount * 0.1 < REACTION_TIME) {
        // 反应时间内：还没开始刹车（人的反应延迟）
        targetAcc = 0.0;
    } else if (ttc < TTC_EMERGENCY) {
        // 紧急区域：最大制动
        targetAcc = MAX_BRAKE;
    } else if (ttc < TTC_WARNING) {
        // 预警区域：舒适制动
        targetAcc = COMFORT_BRAKE;
    }

    // 第三层：渐进刹车（加速度不能瞬间跳变，每步最多变 BRAKE_RATE * 0.1）
    accStep = BRAKE_RATE * 0.1;  // 每步最大变化量
    if (targetAcc < currentAcc - accStep) {
        // 需要减速，但渐进
        cps_i_state.acceleration = d2i(currentAcc - accStep);
    } else if (targetAcc > currentAcc + accStep) {
        // 需要加速，但渐进
        cps_i_state.acceleration = d2i(currentAcc + accStep);
    } else {
        // 够近了，直接到位
        cps_i_state.acceleration = d2i(targetAcc);
    }

    cps_i_state.accRate = d2i(0.0);
}

void reload(){
    makeDecision();
    actID = 0;
}

clock t;

bool ToDecide(){
    if(distanceToGoal <= 2*cps_i_state.velocity){
        return count%N1==0 && count%MAXTIME!=0;
    }
    return count == 1 || (count%N2==0 && count%MAXTIME!=0);
}

bool ToEnd(){
    return count%MAXTIME==0;
}

const int32_t OBS_DECISION_PERIOD = 4;
	uint8_t pc = 0;
	uint8_t tc = 0;

	void followShape(){
	    obs_shape[id].center = obs_i_state[id].position;
	    obs_shape[id].orientation = obs_i_state[id].orientation;
	}

	// Longitudinal action: 0=brake, 1=cruise, 2=accelerate
	int[0,2] chooseLonAction() {
	    int[0,2] action;
	    // No init — UPPAAL exhausts all {0,1,2}
	    return action;
	}

	// Lateral action: -1=left, 0=stay, 1=right
	int[-1,1] chooseLatAction() {
	    int[-1,1] action;
	    // No init — UPPAAL exhausts all {-1,0,1}
	    return action;
	}

	void applyAction(int[0,2] lon, int[-1,1] lat) {
	    double step = mTimeStep(1.0);

	    // Longitudinal execution
	    if (lon == 0) {
	        obs_i_state[id].acceleration = d2i(-i2d(behavior.decMax));
	    } else if (lon == 1) {
	        obs_i_state[id].acceleration = d2i(0.0);
	    } else {
	        obs_i_state[id].acceleration = d2i(i2d(behavior.accMax));
	    }

	    // Lateral execution via yawRate
	    if (lat == -1) {
	        obs_i_state[id].yawRate = d2i(-0.3);
	    } else if (lat == 1) {
	        obs_i_state[id].yawRate = d2i(0.3);
	    } else {
	        obs_i_state[id].yawRate = d2i(0.0);
	    }

	    // Apply acceleration to velocity
	    obs_i_state[id].velocity = obs_i_state[id].velocity +
	        d2i(i2d(obs_i_state[id].acceleration) * step);

	    // Velocity limits
	    if (obs_i_state[id].velocity > behavior.vMax) {
	        obs_i_state[id].velocity = behavior.vMax;
	    }
	    if (obs_i_state[id].velocity < behavior.vMin) {
	        obs_i_state[id].velocity = behavior.vMin;
	    }
	    if (obs_i_state[id].velocity < d2i(0.0)) {
	        obs_i_state[id].velocity = d2i(0.0);
	    }
	}

	void decisionMaking() {
	    int[0,2] lon;
	    int[-1,1] lat;
	    lon = chooseLonAction();
	    lat = chooseLatAction();
	    applyAction(lon, lat);
	}

	void initCon() {
	    obs_dynamic[id].x = initCS.position.x;
	    obs_dynamic[id].y = initCS.position.y;
	    obs_dynamic[id].velocity = mTimeStep(initCS.velocity);
	    obs_dynamic[id].orientation = initCS.orientation;
	}

	void initDis() {
	    obs_i_state[id].position.x = d2i(initCS.position.x);
	    obs_i_state[id].position.y = d2i(initCS.position.y);
	    obs_i_state[id].velocity = d2i(mTimeStep(initCS.velocity));
	    obs_i_state[id].orientation = d2i(initCS.orientation);
	    obs_i_state[id].acceleration = d2i(0.0);
	    obs_i_state[id].yawRate = d2i(0.0);
	}

	void updateDis() {
	    double vx = 0.0, vy = 0.0;
	    double rVelocity = 0.0;
	    double rOrientation = 0.0;
	    int32_t dVx = 0, dVy = 0;

	    rVelocity = i2d(obs_i_state[id].velocity);
	    rOrientation = i2d(obs_i_state[id].orientation);
	    vx = rVelocity*cos(rOrientation);
	    vy = rVelocity*sin(rOrientation);
	    dVx = d2i(vx);
	    dVy = d2i(vy);
	    obs_i_state[id].position.x = obs_i_state[id].position.x + dVx * P*N1;
	    obs_i_state[id].position.y = obs_i_state[id].position.y + dVy * P*N1;
	    followShape();
	}

	void initialize() {
	    pc = 0;
	    tc = 0;
	    initDis();
	    initCon();
	    obs_shape[id] = shape;
	    followShape();
	}

	void change(){
	    updateDis();
	    if (tc % OBS_DECISION_PERIOD == 0) {
	        decisionMaking();
	    }
	    tc++;
	}

int[-100,100] FSAFE = 0;     //rate of reward safe
int[-100,100] FCOMFORT = 0;  //rate of reward comfort
int[-100,100] FPROGRESS = 0; //rate of reward progress

void penalty(){
    bool re_safe = false;
    bool re_comfort = false;
    bool re_progress = false;

    re_safe = isSafe();
    re_progress = isProgress();
    re_comfort = isComfort();

    //normal
    if(re_safe && re_progress && re_comfort){
        FSAFE = 1;
        FCOMFORT = 1;
        FPROGRESS = 1;
    }
    //unsafe
    if(!re_safe){
        FSAFE = -10;
        FCOMFORT = 0;
        FPROGRESS = 0;
    }
    //no progress
    if(re_safe && !re_progress){
        FSAFE = 1;
        FCOMFORT = 1;
        FPROGRESS = -10;
    }
    //discomfort
    if(re_safe && re_progress && !re_comfort){
        FSAFE = 1;
        FCOMFORT = -10;
        FPROGRESS = 1;
    }

    if(cps_i_state.detection.collide || cps_i_state.detection.outside){
        FSAFE = -100;
    }
    if(cps_i_state.detection.reach){
        FPROGRESS = 100;
    }

    reward = 10*re_safe+re_comfort+(5+100*cps_i_state.detection.reach)*re_progress;
}

void terminate(){
    if(!cps_i_state.detection.reach){
        FPROGRESS = -100;
        reward -= 100;
    }else{
        FPROGRESS = 100;  
        reward += 100;      
    }
}

